#!/bin/bash
# Generates Domain G cases, one "y u v" triple per line, to /tmp/cases.txt
OUT=/tmp/cases.txt
: > "$OUT"

# A. all combos of {0,-0} for y/u/v (8)
for y in 0 -0; do for u in 0 -0; do for v in 0 -0; do
  echo "$y $u $v" >> "$OUT"
done; done; done

# B. all combos of {0,-0,0.5,-0.5} for y/u/v (64)
for y in 0 -0 0.5 -0.5; do for u in 0 -0 0.5 -0.5; do for v in 0 -0 0.5 -0.5; do
  echo "$y $u $v" >> "$OUT"
done; done; done

# C. u=v=0 (and signed-zero u/v variants) with various y
YLIST="0 -0 1e-20 37.5 0.5 -0.5 1 -1 2 0.1 -0.1 100 -100 1e-10 -1e-10 1e10 -1e10 5e-324 -5e-324 1e-308 -1e-308 2.2250738585072014e-308 1.7976931348623157e308 -1.7976931348623157e308 3.141592653589793 -2.718281828459045 123.456 -987.654 0.3333333333333333 -0.6666666666666666 1e6 -1e6 0.001 -0.001 7.25 -7.25 0.25 -0.25 0.75 -0.75"
for y in $YLIST; do
  echo "$y 0 0" >> "$OUT"
  echo "$y -0 -0" >> "$OUT"
  echo "$y 0 -0" >> "$OUT"
  echo "$y -0 0" >> "$OUT"
done

# D. two channels tie for max: 1.14*v == 2.032*u  =>  v = u*2.032/1.14
#    vary u and y; compute v with full double precision via awk
for i in $(seq 1 120); do
  awk -v i="$i" 'BEGIN{
    srand(i*7919+13);
    u = (rand()-0.5)*4;            # u in [-2,2)
    if (i%7==0) u = 0;
    if (i%11==0) u = -0.0;
    y = (rand()-0.5)*100;          # y in [-50,50)
    if (i%5==0) y = 0;
    if (i%13==0) y = -0.0;
    if (i%17==0) y = 37.5;
    v = u*2.032/1.14;
    printf "%.17g %.17g %.17g\n", y, u, v;
  }' >> "$OUT"
done
# exact-ratio tie cases with clean decimals
for u in 0 -0 0.5 -0.5 1 -1 0.25 -0.25; do
  for y in 0 -0 0.5 -0.5 37.5 1e-20; do
    awk -v u="$u" -v y="$y" 'BEGIN{ v=u*2.032/1.14; printf "%.17g %.17g %.17g\n", y, u, v }' >> "$OUT"
  done
done

# E. l exactly 0.5 / -0.5 constructions and near misses
echo "0.5 0 0" >> "$OUT"
echo "-0.5 0 0" >> "$OUT"
echo "0.5 -0 -0" >> "$OUT"
echo "-0.5 -0 -0" >> "$OUT"
for i in $(seq 1 40); do
  awk -v i="$i" 'BEGIN{
    srand(i*104729+7);
    y = (rand()<0.5?0.5:-0.5) + (rand()-0.5)*1e-12;
    u = (rand()-0.5)*1e-8;
    v = (rand()-0.5)*1e-8;
    printf "%.17g %.17g %.17g\n", y, u, v;
  }' >> "$OUT"
done

# F. random fill mixing signed zeros, tiny/huge magnitudes, tie-ish values
for i in $(seq 1 160); do
  awk -v i="$i" 'BEGIN{
    srand(i*31+1);
    n=split("0 -0 0.5 -0.5 1e-20 -1e-20 37.5 5e-324 -5e-324 1 -1", pool, " ");
    y=pool[int(rand()*n)+1]; u=pool[int(rand()*n)+1]; v=pool[int(rand()*n)+1];
    if (i%3==0) { u=(rand()-0.5)*2; v=u*2.032/1.14; u=sprintf("%.17g",u); v=sprintf("%.17g",v); }
    printf "%s %s %s\n", y, u, v;
  }' >> "$OUT"
done

wc -l "$OUT"
